import numpy as np

input_grid = [
    [4, 4, 4, 4, 5, 4, 4, 4, 4, 2, 9, 4, 7, 4, 4, 4, 4, 4, 4, 4, 4, 0],
    [0, 4, 2, 4, 5, 4, 4, 4, 4, 2, 4, 4, 7, 6, 8, 4, 4, 4, 4, 4, 4, 0],
    [0, 4, 4, 4, 5, 4, 1, 4, 4, 4, 4, 4, 4, 6, 8, 4, 4, 4, 4, 4, 4, 4],
    [4, 4, 4, 3, 5, 9, 1, 4, 4, 4, 9, 2, 4, 4, 4, 4, 4, 4, 4, 4, 4, 4],
    [4, 4, 2, 4, 5, 9, 1, 4, 4, 4, 9, 4, 4, 6, 8, 6, 4, 4, 4, 4, 4, 0],
    [4, 4, 2, 4, 4, 4, 1, 4, 4, 4, 9, 4, 4, 6, 8, 4, 3, 4, 4, 4, 4, 4],
    [4, 4, 2, 4, 4, 4, 4, 4, 4, 4, 4, 4, 4, 6, 8, 4, 4, 4, 4, 4, 4, 4],
]

# Check connectivity: a cell is kept if it has horizontal OR vertical neighbor of same color
output = []
for r in range(len(input_grid)):
    out_row = []
    for c in range(len(input_grid[0])):
        cell = input_grid[r][c]
        neighbors = []
        if r > 0: neighbors.append(input_grid[r-1][c])
        if r < len(input_grid)-1: neighbors.append(input_grid[r+1][c])
        if c > 0: neighbors.append(input_grid[r][c-1])
        if c < len(input_grid[0])-1: neighbors.append(input_grid[r][c+1])
        # Keep if any neighbor has same color
        if any(n == cell for n in neighbors):
            out_row.append(cell)
        else:
            out_row.append(0)
    output.append(out_row)

print("Output based on horizontal connectivity:")
for row in output:
    print(' '.join(str(x) for x in row))

